1	//! The genetics lane: a coding sequence read as a word in the twelve.
2	//!
3	//! Not an analogy. The twelve operations and the twelve axes are one alphabet,
4	//! read as an operation or as an axis according to where the glyph stands. The
5	//! chain from nucleotide to glyph is proved in Lean and parsed into
6	//! `genetic_table.rs` by its generator: G is B because guanine wobble-pairs
7	//! with both C and U, C is T because it pairs only with G, A is F, U is N;
8	//! codons carry to amino acids by the genetic code; and exactly twelve amino
9	//! acids are promoted, bijecting the twelve axes.
10	//!
11	//! So a gene is already a word, and the same SIXTEEN_3 engine that verdicts x86
12	//! verdicts the transcript.
13	
14	use alloc::string::String;
15	use alloc::vec::Vec;
16	use crate::genetic_table::{AA_GLYPH, CODON, NUC_B4};
17	
18	/// One promoted codon, as read.
19	pub struct Read { pub codon: String, pub aa: &'static str, pub glyph: char, pub axis: &'static str }
20	
21	/// What a lifted sequence says.
22	pub struct Transcript {
23	    pub word: Vec<char>,
24	    pub reading: Vec<Read>,
25	    /// the stop codon that ended the reading frame, if one did
26	    pub stopped: Option<&'static str>,
27	    /// the frame start, as an offset into the cleaned sequence
28	    pub start: usize,
29	    /// true when no AUG was found and the frame starts at zero
30	    pub implicit_frame: bool,
31	}
32	
33	/// Belnap value of a nucleotide.
34	pub fn nuc_b4(c: char) -> Option<char> {
35	    NUC_B4.iter().find(|(n, _)| *n == c).map(|(_, b)| *b)
36	}
37	
38	fn codon_meaning(c: &str) -> Option<(&'static str, &'static str)> {
39	    CODON.iter().find(|(k, _, _)| *k == c).map(|(_, kind, val)| (*kind, *val))
40	}
41	
42	fn aa_glyph(aa: &str) -> Option<(char, &'static str)> {
43	    AA_GLYPH.iter().find(|(a, _, _, _)| *a == aa).map(|(_, g, ax, _)| (*g, *ax))
44	}
45	
46	/// An RNA or DNA sequence to a word in the twelve. Reads from the first AUG in
47	/// frame, stops at a stop codon, and emits a glyph only where the codon names a
48	/// promoted amino acid; the ground layer activates no axis and is silent, which
49	/// is a fact of the code and not a gap in the lift.
50	pub fn lift_rna(seq: &str) -> Transcript {
51	    let clean: Vec<char> = seq.chars()
52	        .map(|c| c.to_ascii_uppercase())
53	        .filter(|c| matches!(c, 'A' | 'C' | 'G' | 'T' | 'U'))
54	        .map(|c| if c == 'T' { 'U' } else { c })
55	        .collect();
56	
57	    let mut start = 0usize;
58	    let mut implicit_frame = true;
59	    for k in 0..clean.len().saturating_sub(2) {
60	        if clean[k] == 'A' && clean[k + 1] == 'U' && clean[k + 2] == 'G' {
61	            start = k; implicit_frame = false; break;
62	        }
63	    }
64	
65	    let mut t = Transcript { word: Vec::new(), reading: Vec::new(), stopped: None, start, implicit_frame };
66	    let mut k = start;
67	    while k + 3 <= clean.len() {
68	        let codon: String = clean[k..k + 3].iter().collect();
69	        if let Some((kind, val)) = codon_meaning(&codon) {
70	            if kind == "stop" { t.stopped = Some(val); break; }
71	            if let Some((glyph, axis)) = aa_glyph(val) {
72	                t.word.push(glyph);
73	                t.reading.push(Read { codon, aa: val, glyph, axis });
74	            }
75	        }
76	        k += 3;
77	    }
78	    t
79	}
80	
81	/// The one-letter code of a promoted amino acid, or None for the ground layer.
82	/// A protein arrives as residues, one layer past the codons `lift_rna` reads —
83	/// the codon degeneracy is already collapsed, so this reads the sequence directly.
84	/// The eight ground-layer amino acids (A G P T S R L V) activate no axis and are
85	/// silent, exactly as their codons are in the transcript.
86	fn one_letter_aa(c: char) -> Option<&'static str> {
87	    Some(match c.to_ascii_uppercase() {
88	        'M' => "Met", 'W' => "Trp", 'C' => "Cys", 'Y' => "Tyr",
89	        'F' => "Phe", 'I' => "Ile", 'N' => "Asn", 'Q' => "Gln",
90	        'H' => "His", 'D' => "Asp", 'K' => "Lys", 'E' => "Glu",
91	        // ground layer — real residues, no promoted axis:
92	        'A' | 'G' | 'P' | 'T' | 'S' | 'R' | 'L' | 'V' => return None,
93	        _ => return None,
94	    })
95	}
96	
97	/// Three-letter residue name (PDB ATOM records, some FASTA) to one-letter.
98	fn three_to_one(res: &str) -> Option<char> {
99	    Some(match res.to_ascii_uppercase().as_str() {
100	        "MET" => 'M', "TRP" => 'W', "CYS" => 'C', "TYR" => 'Y', "PHE" => 'F',
101	        "ILE" => 'I', "ASN" => 'N', "GLN" => 'Q', "HIS" => 'H', "ASP" => 'D',
102	        "LYS" => 'K', "GLU" => 'E', "ALA" => 'A', "GLY" => 'G', "PRO" => 'P',
103	        "THR" => 'T', "SER" => 'S', "ARG" => 'R', "LEU" => 'L', "VAL" => 'V',
104	        _ => return None,
105	    })
106	}
107	
108	/// A protein — an amino-acid sequence — lifted to a word in the twelve. The same
109	/// act as `lift_rna` one layer up: each promoted residue emits its glyph, the
110	/// ground layer is silent. One-letter input; a residue that is not an amino acid
111	/// (a gap, an X, whitespace) is skipped.
112	pub fn lift_protein(seq: &str) -> Transcript {
113	    let mut t = Transcript { word: Vec::new(), reading: Vec::new(), stopped: None, start: 0, implicit_frame: true };
114	    for (i, c) in seq.chars().enumerate() {
115	        if c.is_whitespace() { continue; }
116	        if let Some(aa) = one_letter_aa(c) {
117	            if let Some((glyph, axis)) = aa_glyph(aa) {
118	                t.word.push(glyph);
119	                t.reading.push(Read { codon: format!("{}", i + 1), aa, glyph, axis });
120	            }
121	        }
122	    }
123	    t
124	}
125	
126	/// Pull the residue sequence out of a PDB, one letter per residue, reading the
127	/// CA atom of each so an all-atom file yields one residue per position rather than
128	/// one per atom. Chain breaks are not marked — the fold is one word.
129	pub fn protein_from_pdb(text: &str) -> String {
130	    let mut seq = String::new();
131	    for line in text.lines() {
132	        if !(line.starts_with("ATOM") || line.starts_with("HETATM")) { continue; }
133	        if line.len() < 20 { continue; }
134	        let atom = line.get(12..16).map(|s| s.trim()).unwrap_or("");
135	        if atom != "CA" { continue; }
136	        let res = line.get(17..20).map(|s| s.trim()).unwrap_or("");
137	        // Most PDBs name residues in three letters (MET); the odot/DARPin designs
138	        // here name them in one (M). Take the three-letter reading when it maps,
139	        // else accept a lone alphabetic character as already a one-letter code.
140	        if let Some(c) = three_to_one(res) {
141	            seq.push(c);
142	        } else if res.len() == 1 {
143	            if let Some(ch) = res.chars().next() {
144	                if ch.is_ascii_alphabetic() { seq.push(ch.to_ascii_uppercase()); }
145	            }
146	        }
147	    }
148	    seq
149	}
150	
151	/// FASTA to a bare sequence: drop the header lines, concatenate the rest.
152	pub fn protein_from_fasta(text: &str) -> String {
153	    text.lines().filter(|l| !l.starts_with('>')).collect::<Vec<_>>().join("")
154	}
155	
156	/// A glycosylation site found on a peptide — the boundary interface where a glycan
157	/// attaches. N-linked sites are the sequon Asn-X-[Ser/Thr] with X not Proline;
158	/// O-linked sites are a Ser or Thr, reported separately because they carry no
159	/// promoted glyph (both are ground-layer) and so are invisible in the word itself.
160	pub struct GlycoSite {
161	    pub pos: usize,          // 1-based residue index of the anchor
162	    pub kind: &'static str,  // "N-linked" | "O-linked"
163	    pub motif: String,       // the residues that make the site
164	    pub glyph: Option<char>, // the anchor's mark, where it has one (Asn = ∈)
165	}
166	
167	/// Locate every glycosylation boundary interface on a one-letter peptide. The
168	/// glycan tree that hangs off each site is a separate object — a branched word in
169	/// its own right — and needs the monosaccharides grounded before it can be lifted;
170	/// this names WHERE the boundary is, which is the half that reads off the peptide
171	/// with no new grounding. N-linked anchors are Asn, which is ∈ (the recognition
172	/// gate), so an N-site is an ∈ in the peptide word that opens a sequon.
173	pub fn glyco_sites(seq: &str) -> Vec<GlycoSite> {
174	    let res: Vec<char> = seq.chars()
175	        .filter(|c| c.is_ascii_alphabetic())
176	        .map(|c| c.to_ascii_uppercase())
177	        .collect();
178	    let mut sites = Vec::new();
179	    for i in 0..res.len() {
180	        // N-linked sequon: N - X(≠P) - S|T
181	        if res[i] == 'N' && i + 2 < res.len() && res[i + 1] != 'P'
182	            && (res[i + 2] == 'S' || res[i + 2] == 'T') {
183	            sites.push(GlycoSite {
184	                pos: i + 1,
185	                kind: "N-linked",
186	                motif: res[i..=i + 2].iter().collect(),
187	                glyph: aa_glyph("Asn").map(|(g, _)| g),
188	            });
189	        }
190	    }
191	    // O-linked: Ser/Thr are candidates, reported but not every S/T is glycosylated;
192	    // flagged as sites the sequence ADMITS, distinct from the determinate N-sequon.
193	    for i in 0..res.len() {
194	        if res[i] == 'S' || res[i] == 'T' {
195	            sites.push(GlycoSite {
196	                pos: i + 1,
197	                kind: "O-linked",
198	                motif: String::from(res[i]),
199	                glyph: None,
200	            });
201	        }
202	    }
203	    sites.sort_by_key(|s| s.pos);
204	    sites
205	}
206	
207	/// The vertebrate mitochondrial code differs from the standard one in four
208	/// codons. Reading a mitochondrial gene with the standard table terminates it
209	/// early, and one of the differences matters to the alphabet directly: UGA is a
210	/// terminator in the standard code and tryptophan here, which is the mark that
211	/// closes a reading.
212	pub fn dialect_override(dialect: &str, codon: &str) -> Option<(&'static str, &'static str)> {
213	    match dialect {
214	        "mitochondrial" | "mito" | "vertebrate_mitochondrial" => match codon {
215	            "AUA" => Some(("aa", "Met")),
216	            "UGA" => Some(("aa", "Trp")),
217	            "AGA" => Some(("stop", "AGA")),
218	            "AGG" => Some(("stop", "AGG")),
219	            _ => None,
220	        },
221	        _ => None,
222	    }
223	}
224	
225	/// A residue sequence to a word. One-letter codes; anything unrecognised is
226	/// skipped, as the eight silent residues are.
227	pub fn lift_peptide(seq: &str) -> Transcript {
228	    const ONE: [(char, &str); 20] = [
229	        ('A', "Ala"), ('R', "Arg"), ('N', "Asn"), ('D', "Asp"), ('C', "Cys"),
230	        ('Q', "Gln"), ('E', "Glu"), ('G', "Gly"), ('H', "His"), ('I', "Ile"),
231	        ('L', "Leu"), ('K', "Lys"), ('M', "Met"), ('F', "Phe"), ('P', "Pro"),
232	        ('S', "Ser"), ('T', "Thr"), ('W', "Trp"), ('Y', "Tyr"), ('V', "Val"),
233	    ];
234	    let mut t = Transcript {
235	        word: Vec::new(), reading: Vec::new(), stopped: None,
236	        start: 0, implicit_frame: false,
237	    };
238	    for c in seq.chars().map(|c| c.to_ascii_uppercase()) {
239	        if let Some((_, aa)) = ONE.iter().find(|(l, _)| *l == c) {
240	            if let Some((glyph, axis)) = aa_glyph(aa) {
241	                t.word.push(glyph);
242	                let mut buf = [0u8; 4];
243	                t.reading.push(Read {
244	                    codon: String::from(c.encode_utf8(&mut buf)), aa, glyph, axis,
245	                });
246	            }
247	        }
248	    }
249	    t
250	}
251	
252	/// An RNA or DNA sequence read in a named genetic code.
253	pub fn lift_rna_dialect(seq: &str, dialect: &str) -> Transcript {
254	    let clean: Vec<char> = seq.chars()
255	        .map(|c| c.to_ascii_uppercase())
256	        .filter(|c| matches!(c, 'A' | 'C' | 'G' | 'T' | 'U'))
257	        .map(|c| if c == 'T' { 'U' } else { c })
258	        .collect();
259	
260	    let mut start = 0usize;
261	    let mut implicit_frame = true;
262	    for k in 0..clean.len().saturating_sub(2) {
263	        if clean[k] == 'A' && clean[k + 1] == 'U' && clean[k + 2] == 'G' {
264	            start = k; implicit_frame = false; break;
265	        }
266	    }
267	
268	    let mut t = Transcript { word: Vec::new(), reading: Vec::new(), stopped: None, start, implicit_frame };
269	    let mut k = start;
270	    while k + 3 <= clean.len() {
271	        let codon: String = clean[k..k + 3].iter().collect();
272	        let meaning = dialect_override(dialect, &codon).or_else(|| codon_meaning(&codon));
273	        if let Some((kind, val)) = meaning {
274	            if kind == "stop" { t.stopped = Some(val); break; }
275	            if let Some((glyph, axis)) = aa_glyph(val) {
276	                t.word.push(glyph);
277	                t.reading.push(Read { codon, aa: val, glyph, axis });
278	            }
279	        }
280	        k += 3;
281	    }
282	    t
283	}
