147	fn selfread(path: &str) -> i32 {
148	    let raw = match std::fs::read(path) {
149	        Ok(r) => r,
150	        Err(e) => { eprintln!("cannot read {}: {}", path, e); return 2; }
151	    };
152	    let l = loader::load(&raw);
153	    let image = vox_decode::Image { segments: l.code.clone() };
154	    let mut seeds: Vec<u64> = l.symbols.values().copied().collect();
155	    seeds.push(l.entry);
156	    let w = vox_decode::walk(&image, l.entry, &seeds);
157	
158	    let mut tally = [0usize; 4];
159	    let mut by_exit: std::collections::BTreeMap<i32, (usize, i64)> = std::collections::BTreeMap::new();
160	    let mut worst: Vec<(i32, u64, i32, i32)> = Vec::new();   // residual, addr, surplus, exits
161	    for (addr, f) in &w.functions {
162	        let word = vox::recompile_function(f);
163	        match vox::verdict(&word) { 'T'=>tally[0]+=1, 'B'=>tally[1]+=1, 'N'=>tally[2]+=1, _=>tally[3]+=1 }
164	        let o = vox::open_forks(&word);
165	        let e = by_exit.entry(o.exits.min(4)).or_insert((0, 0));
166	        e.0 += 1; e.1 += o.surplus as i64;
167	        if o.residual > 0 { worst.push((o.residual, *addr, o.surplus, o.exits)); }
168	    }
169	    worst.sort_by(|a, b| b.0.cmp(&a.0));
170	
171	    println!("{}  {}  {} function(s) by descent", path, l.format, w.functions.len());
172	    println!("  verdicts  T {}   B {}   N {}   F {}", tally[0], tally[1], tally[2], tally[3]);
173	    println!("  F is zero when the decoder is in phase with the image.\n");
174	    println!("  open forks against exits — an early return is a fork that never rejoins:");
175	    println!("    {:>6}  {:>7}  {:>14}", "exits", "funcs", "mean surplus");
176	    for (k, (n, sum)) in &by_exit {
177	        println!("    {:>5}{}  {:>7}  {:>14.2}", k, if *k == 4 { "+" } else { " " }, n, *sum as f64 / *n as f64);
178	    }
179	    println!("\n  {} function(s) carry surplus the exits do not explain; deepest first:", worst.len());
180	    for (res, addr, sur, ex) in worst.iter().take(10) {
181	        println!("    0x{:<8x}  residual {:>3}   surplus {:>3}   exits {}", addr, res, sur, ex);
182	    }
183	    println!("\n  Ranking by raw surplus ranks by how many ways a function can return.");
184	    println!("  The residual is what is left once that is paid for.");
185	    0
186	}
