188	fn audit_linear(path: &str, l: &loader::Loaded, bits: u8) -> i32 {
189	    let total: usize = l.code.iter().map(|(_, b)| b.len()).sum();
190	    println!("{}  {} {}  entry 0x{:x}  {} byte(s) of code", path, l.format, l.arch, l.entry, total);
191	    let mut tally = [0usize; 4]; let mut funcs = 0usize; let mut covered = 0usize;
192	    let mut b_findings: Vec<(u64, String)> = Vec::new();
193	    for (base, bytes) in &l.code {
194	        let mut pos = 0usize; let mut cur: Vec<x86::Insn> = Vec::new(); let mut fstart = *base;
195	        let mut flush = |cur: &mut Vec<x86::Insn>, fstart: u64, tally: &mut [usize;4], funcs: &mut usize, bf: &mut Vec<(u64,String)>| {
196	            if cur.is_empty() { return; }
197	            let word = alloc_word(cur);
198	            let v = vox::verdict(&word);
199	            match v { 'T'=>tally[0]+=1,'B'=>tally[1]+=1,'N'=>tally[2]+=1,_=>tally[3]+=1 }
200	            if v == 'B' && bf.len() < 40 { bf.push((fstart, vox::glyphs(&word))); }
201	            *funcs += 1; cur.clear();
202	        };
203	        while pos < bytes.len() {
204	            let addr = base + pos as u64;
205	            match x86::decode_mode(&bytes[pos..], addr, bits) {
206	                Some(d) if d.len > 0 => {
207	                    if cur.is_empty() { fstart = addr; }
208	                    let mn = d.mnemonic.clone(); covered += d.len; pos += d.len;
209	                    let term = mn.starts_with("ret") || matches!(mn.as_str(), "int3"|"ud2"|"hlt"|"jmp");
210	                    cur.push(d);
211	                    if term { flush(&mut cur, fstart, &mut tally, &mut funcs, &mut b_findings); }
212	                }
213	                _ => { flush(&mut cur, fstart, &mut tally, &mut funcs, &mut b_findings); pos += 1; }
214	            }
215	        }
216	        flush(&mut cur, fstart, &mut tally, &mut funcs, &mut b_findings);
217	    }
218	    println!("  {} function(s) by linear sweep, {}% decoded ({} of {} bytes)",
219	        funcs, (covered*100/total.max(1)).min(100), covered.min(total), total);
220	    println!("  verdicts  T {}   B {}   N {}   F {}", tally[0], tally[1], tally[2], tally[3]);
221	    for (a, w) in b_findings.iter().take(12) { println!("    0x{:x}  {}", a, w); }
222	    0
223	}
