225	/// Lift a decoded run to a word. This goes through `vox::recompile_function`
226	/// so the merge pass runs: without it no ∋ is ever emitted, every fork reads as
227	/// dangling, and the lane cannot return T at all.
228	fn alloc_word(insns: &[x86::Insn]) -> Vec<char> {
229	    let lifted: Vec<vox::Instruction> = insns.iter().map(|i| vox::Instruction {
230	        address: i.addr,
231	        mnemonic: i.mnemonic.clone(),
232	        op_str: if let (true, Some(t)) = (i.ops.len() == 1, i.target) { format!("{:#x}", t) }
233	                else { i.ops.iter().map(|o| o.intel()).collect::<Vec<_>>().join(", ") },
234	    }).collect();
235	    vox::recompile_function(&lifted)
236	}
237	fn alloc_prefix() -> Vec<char> { vec!['⊢'] }
