239	fn lift_file(path: &str) -> i32 {
240	    let raw = match std::fs::read(path) {
241	        Ok(r) => r,
242	        Err(e) => { eprintln!("cannot read {}: {}", path, e); return 2; }
243	    };
244	    let l = loader::load(&raw);
245	    if l.code.is_empty() {
246	        eprintln!("{}: no executable sections found", path);
247	        return 1;
248	    }
249	    if l.arch != "x86-64" && l.arch != "x86-32" {
250	        eprintln!("{}: {} {} code. V⊙x decodes x86; it will not misread another", path, l.format, l.arch);
251	        eprintln!("architecture and hand back a confident, wrong word.");
252	        return 3;
253	    }
254	    if l.arch == "x86-32" {
255	        return audit_linear(path, &l, 32);
256	    }
257	    let image = vox_decode::Image { segments: l.code };
258	    println!("{}  {}  entry 0x{:x}  {} byte(s) of code", path, l.format, l.entry, image.total_bytes());
259	    let mut seeds: Vec<u64> = l.symbols.values().copied().collect(); seeds.push(l.entry);
260	    let w = vox_decode::walk(&image, l.entry, &seeds);
261	    let decoded: usize = w.functions.iter().map(|f| f.1.len()).sum();
262	    println!("  {} function(s), {} instruction(s)", w.functions.len(), decoded);
263	    println!("  claimed {}% of the image ({} of {} bytes)",
264	        w.claimed_percent(), w.claimed_bytes, w.total_bytes);
265	
266	    let mut tally = [0usize; 4]; // T B N F
267	    let mut illtyped: Vec<(u64, String)> = Vec::new();
268	    let mut descent_f = 0usize;
269	    // recursive-descent functions: the trustworthy set
270	    let mut claimed: std::collections::BTreeSet<u64> = std::collections::BTreeSet::new();
271	    for (start, f) in &w.functions {
272	        for ins in f { claimed.insert(ins.address); }
273	        let word = vox::recompile_function(f);
274	        match vox::verdict(&word) {
275	            'T' => tally[0] += 1, 'B' => tally[1] += 1, 'N' => tally[2] += 1,
276	            _ => { tally[3] += 1; descent_f += 1; if illtyped.len() < 8 { illtyped.push((*start, vox::glyphs(&word))); } }
277	        }
278	    }
279	    let descended = w.functions.len();
280	    // fallback sweep: linear-decode what descent never reached, group into
281	    // functions of their own at each terminal, and verdict those too.
282	    let mut swept = 0usize; let mut swept_bytes = 0usize;
283	    let mut sweep_f = 0usize;
284	    for (base, bytes) in &image.segments {
285	        let mut pos = 0usize;
286	        let mut cur: Vec<x86::Insn> = Vec::new();
287	        let flush = |cur: &mut Vec<x86::Insn>, tally: &mut [usize;4], swept: &mut usize, sweep_f: &mut usize| {
288	            if cur.is_empty() { return; }
289	            let mut word = alloc_word(cur);
290	            match vox::verdict(&word) { 'T'=>tally[0]+=1,'B'=>tally[1]+=1,'N'=>tally[2]+=1,_=>{tally[3]+=1; *sweep_f+=1;} }
291	            *swept += 1; word.clear(); cur.clear();
292	        };
293	        while pos < bytes.len() {
294	            let addr = base + pos as u64;
295	            if claimed.contains(&addr) { flush(&mut cur, &mut tally, &mut swept, &mut sweep_f);
296	                // skip the claimed instruction
297	                if let Some(d) = x86::decode(&bytes[pos..], addr) { pos += d.len.max(1); } else { pos += 1; }
298	                continue;
299	            }
300	            match x86::decode(&bytes[pos..], addr) {
301	                Some(d) if d.len > 0 => {
302	                    let mn = d.mnemonic.clone(); swept_bytes += d.len; pos += d.len;
303	                    let terminal = mn.starts_with("ret") || matches!(mn.as_str(), "int3"|"ud2"|"hlt"|"jmp");
304	                    cur.push(d);
305	                    if terminal { flush(&mut cur, &mut tally, &mut swept, &mut sweep_f); }
306	                }
307	                _ => { flush(&mut cur, &mut tally, &mut swept, &mut sweep_f); pos += 1; }
308	            }
309	        }
310	        flush(&mut cur, &mut tally, &mut swept, &mut sweep_f);
311	    }
312	    let total_cov = w.claimed_bytes + swept_bytes;
313	    println!();
314	    if swept > 0 {
315	        println!("  {} function(s) by descent, {} more by fallback sweep", descended, swept);
316	        println!("  covered {}% of the image ({} of {} bytes)",
317	            (total_cov*100/w.total_bytes.max(1)).min(100), total_cov.min(w.total_bytes), w.total_bytes);
318	    }
319	    println!("  verdicts  T {}   B {}   N {}   F {}  (F: {} from descent, {} from fallback sweep)",
320	        tally[0], tally[1], tally[2], tally[3], descent_f, sweep_f);
321	    for (a, g) in &illtyped {
322	        let head: String = g.chars().take(90).collect();
323	        println!("    0x{:x}  {}", a, head);
324	    }
325	    0
326	}
