328	fn lane(isa: &str, word: &[char]) -> i32 {
329	    let v = vox::verdict(word);
330	    let mark = if v == 'B' { "   <-- FINDING (fork open across commit)" } else { "" };
331	    println!("{:<6} {}  {}{}", isa, v, vox::glyphs(word), mark);
332	    0
333	}
