335	fn selftest() -> i32 {
336	    // Planted glyph words: the auditor's own law, independent of any decoder.
337	    // ⊢ open ∈ fork ⊡ commit ⊣ terminal ∋ merge
338	    let cases: &[(&str, &str, char)] = &[
339	        ("linear routine, never forks",        "⊢⊡⊣",   'N'),
340	        ("fork that merges before terminal",   "⊢∈⊡∋⊣", 'T'),
341	        ("fork held open across the terminal", "⊢∈⊡⊣",  'B'),
342	        ("merge with nothing to pair",         "⊢∋⊣",   'F'),
343	    ];
344	    let mut ok = true;
345	    for (name, w, want) in cases {
346	        let word: Vec<char> = w.chars().collect();
347	        let got = vox::verdict(&word);
348	        let mark = if got == *want { "ok" } else { ok = false; "FAIL" };
349	        println!("  {:<38} {}  {}  (expect {})  {}", name, w, got, want, mark);
350	    }
351	    // EVM and WASM bytecode: a state commit inside an unmerged branch (B) vs
352	    // paths that rejoin before the commit (T). Same law, real bytes.
353	    let bc: &[(&str, char, Vec<char>)] = &[
354	        ("EVM reentrant (commit in unmerged branch)", 'B', lanes::evm_word("600160075755005b00")),
355	        ("EVM guarded  (paths merge before commit)",  'T', lanes::evm_word("6001600657545b5500")),
356	        ("WASM reentrant (commit + return in branch)", 'B', lanes::wasm_word("20000440410141003602000f0b0b")),
357	        ("WASM guarded  (if merges before commit)",    'T', lanes::wasm_word("2000044010000b410041003602000b")),
358	    ];
359	    for (name, want, word) in bc {
360	        let got = vox::verdict(word);
361	        let mark = if got == *want { "ok" } else { ok = false; "FAIL" };
362	        println!("  {:<42} {}  (expect {})  {}", name, got, want, mark);
363	    }
364	    if ok { println!("selftest OK: the closure law holds on x86, EVM and WASM."); 0 }
365	    else { eprintln!("selftest FAILED"); 1 }
366	}
367	
368	
369	/// Read a file, or say which one and why, and leave without a backtrace.
370	///
371	/// `.expect("read")` printed `read: Os { code: 2 }` and a panic notice, naming
372	/// neither the path nor the verb. Fed a list of a few hundred binaries — which is
373	/// how this is actually used — that is a wall of identical panics with nothing in
374	/// them to act on, and the one path that was wrong stays hidden.
375	fn read_or_exit(path: &str) -> Vec<u8> {
376	    match std::fs::read(path) {
377	        Ok(b) => b,
378	        Err(e) => {
379	            eprintln!("vox: cannot read {}: {}", path, e);
380	            std::process::exit(2);
381	        }
382	    }
383	}
384	
385	/// Real file and console I/O for `imasm_vm::Machine::run_process`, backed by
386	/// actual `std::fs`/stdio. A guest that opens, reads, or writes a file under
387	/// this does so for real, under whatever permission this process already
388	/// has — the same access the shell that launched `vox` already had.
389	struct StdHost { files: std::collections::BTreeMap<i32, std::fs::File>, next_fd: i32 }
390	impl StdHost { fn new() -> Self { StdHost { files: std::collections::BTreeMap::new(), next_fd: 100 } } }
391	impl imasm_vm::Host for StdHost {
392	    fn open(&mut self, path: &str, flags: i32, mode: i32) -> i32 {
393	        let mut opts = std::fs::OpenOptions::new();
394	        let acc = flags & 0b11;
395	        opts.read(acc == 0 || acc == 2).write(acc == 1 || acc == 2);
396	        if flags & 0o100 != 0 { opts.create(true); }
397	        if flags & 0o1000 != 0 { opts.truncate(true); }
398	        if flags & 0o2000 != 0 { opts.append(true); }
399	        #[cfg(unix)] { use std::os::unix::fs::OpenOptionsExt; opts.mode(mode as u32); }
400	        #[cfg(not(unix))] { let _ = mode; }
401	        match opts.open(path) {
402	            Ok(f) => { let fd = self.next_fd; self.next_fd += 1; self.files.insert(fd, f); fd }
403	            Err(_) => -2, // ENOENT: a precise errno map is a further rung
404	        }
405	    }
406	    fn read(&mut self, fd: i32, buf: &mut [u8]) -> i64 {
407	        use std::io::Read;
408	        match fd {
409	            0 => std::io::stdin().read(buf).map(|n| n as i64).unwrap_or(-5),
410	            _ => match self.files.get_mut(&fd) { Some(f) => f.read(buf).map(|n| n as i64).unwrap_or(-5), None => -9 },
411	        }
412	    }
413	    fn write(&mut self, fd: i32, buf: &[u8]) -> i64 {
414	        use std::io::Write;
415	        match fd {
416	            1 => std::io::stdout().write_all(buf).map(|_| buf.len() as i64).unwrap_or(-5),
417	            2 => std::io::stderr().write_all(buf).map(|_| buf.len() as i64).unwrap_or(-5),
418	            _ => match self.files.get_mut(&fd) { Some(f) => f.write(buf).map(|n| n as i64).unwrap_or(-5), None => -9 },
419	        }
420	    }
421	    fn close(&mut self, fd: i32) -> i32 {
422	        if matches!(fd, 0|1|2) { return 0; }
423	        if self.files.remove(&fd).is_some() { 0 } else { -9 }
424	    }
425	}
426	
427	fn main() {
428	    let args: Vec<String> = std::env::args().skip(1).collect();
429	    let code = match args.first().map(|s| s.as_str()) {
430	        None | Some("-h") | Some("--help") | Some("help") => { usage(); 0 }
431	        Some("--selftest") | Some("--self-test") | Some("selftest") | Some("self-test") => selftest(),
432	        Some("verdict") => {
433	            // A word given as an ARGUMENT is capped by the OS's argv limit, and a
434	            // lifted proof term runs to tens of thousands of glyphs — the words this
435	            // is most wanted for are exactly the ones that will not fit. `-` reads
436	            // the word from stdin instead, and prints only the verdict, so a sweep
437	            // can pipe thousands through without the shell in the way.
438	            if args.len() < 2 { eprintln!("vox verdict <glyph-word> | vox verdict - (word on stdin) | vox verdict --tsv <file>"); 1 }
439	            else if args[1] == "--tsv" {
440	                // A sweep hands over thousands of lifted words at once. Spawning a
441	                // process per word makes the shell the bottleneck and, worse, makes
442	                // it tempting to reimplement the verdict on the caller's side. One
443	                // process, one authority: `name<TAB>word` in, `name<TAB>verdict<TAB>len`
444	                // out, in input order. A blank word is not verdicted — it is
445	                // reported as `-`, since a word nobody lifted is not a word that
446	                // failed to close.
447	                if args.len() < 3 { eprintln!("vox verdict --tsv <file>"); 1 }
448	                else {
449	                    match std::fs::read_to_string(&args[2]) {
450	                        Err(e) => { eprintln!("vox verdict --tsv: {}: {}", args[2], e); 1 }
451	                        Ok(txt) => {
452	                            let mut counts = std::collections::BTreeMap::new();
453	                            for line in txt.lines() {
454	                                if line.trim().is_empty() { continue; }
455	                                let mut it = line.splitn(2, '\t');
456	                                let name = it.next().unwrap_or("");
457	                                let w = it.next().unwrap_or("").trim();
458	                                if w.is_empty() {
459	                                    println!("{}\t-\t0", name);
460	                                    *counts.entry('-').or_insert(0usize) += 1;
461	                                    continue;
462	                                }
463	                                let word: Vec<char> = w.chars().collect();
464	                                let v = vox::verdict(&word);
465	                                *counts.entry(v).or_insert(0usize) += 1;
466	                                println!("{}\t{}\t{}", name, v, word.len());
467	                            }
468	                            let total: usize = counts.values().sum();
469	                            let tally: Vec<String> = counts.iter().map(|(k, n)| format!("{} {}", k, n)).collect();
470	                            eprintln!("verdicted {} words: {}", total, tally.join("  "));
471	                            0
472	                        }
473	                    }
474	                }
475	            }
476	            else if args[1] == "-" {
477	                use std::io::Read;
478	                let mut buf = String::new();
479	                match std::io::stdin().read_to_string(&mut buf) {
480	                    Err(_) => { eprintln!("vox verdict -: could not read stdin"); 1 }
481	                    Ok(_) => {
482	                        let word: Vec<char> = buf.trim().chars().collect();
483	                        println!("verdict {}", vox::verdict(&word));
484	                        0
485	                    }
486	                }
487	            }
488	            else {
489	                let word: Vec<char> = args[1..].join("").chars().collect();
490	                println!("{}", vox::glyphs(&word));
491	                println!("verdict {}", vox::verdict(&word));
492	                0
493	            }
494	        }
495	        Some("pairs") | Some("pairing") => {
496	            if args.len() < 2 { eprintln!("vox pairs <glyph-word>"); 1 }
497	            else {
498	                let word: Vec<char> = args[1..].join("").chars().collect();
499	                let (regions, un_split, un_fuse) = vox::pairing(&word);
500	                println!("{:<7}{:<7}{:<7}{:<6}{}", "OPEN", "CLOSE", "SPAN", "WORK", "INTERIOR");
501	                for r in &regions {
502	                    let span = (r.fuse + word.len() - r.split) % word.len();
503	                    println!("{:<7}{:<7}{:<7}{:<6}{}", r.split, r.fuse, span,
504	                        if r.substantial { "yes" } else { "no" }, r.interior);
505	                }
506	                println!();
507	                println!("letters      {}", word.len());
508	                println!("regions      {} paired, {} substantial", regions.len(),
509	                    regions.iter().filter(|r| r.substantial).count());
510	                let ds: Vec<String> = un_split.iter().map(|i| i.to_string()).collect();
511	                let fs: Vec<String> = un_fuse.iter().map(|i| i.to_string()).collect();
512	                println!("unanswered   {} division(s) at {}", un_split.len(),
513	                    if ds.is_empty() { "-".to_string() } else { ds.join(",") });
514	                println!("unopened     {} rejoining(s) at {}", un_fuse.len(),
515	                    if fs.is_empty() { "-".to_string() } else { fs.join(",") });
516	                println!("verdict      {}", vox::verdict(&word));
517	                0
518	            }
519	        }
520	        Some("classify") => {
521	            if args.len() < 2 { eprintln!("vox classify <mnemonic> [operands]"); 1 }
522	            else {
523	                let ins = vox::Instruction { address: 0, mnemonic: args[1].to_lowercase(), op_str: args[2..].join(" ") };
524	                println!("{} {}", ins.mnemonic, vox::classify_instruction(&ins));
525	                0
526	            }
527	        }
528	        Some("evm") | Some("--evm") => { if args.len() < 2 { eprintln!("vox evm <hex>"); 1 } else { lane("EVM", &lanes::evm_word(&args[1])) } }
529	        Some("wasm") | Some("--wasm") => { if args.len() < 2 { eprintln!("vox wasm <hex>"); 1 } else { lane("WASM", &lanes::wasm_word(&args[1])) } }
530	        Some("rna") | Some("--rna") => {
531	            if args.len() < 2 { eprintln!("vox rna <sequence> [--dialect mito]"); 1 }
532	            else {
533	                let mut dialect = String::new();
534	                let mut seq = String::new();
535	                let mut it = args[1..].iter();
536	                while let Some(a) = it.next() {
537	                    if a == "--dialect" { dialect = it.next().cloned().unwrap_or_default(); }
538	                    else { seq.push_str(a); }
539	                }
540	                rna(&seq, &dialect)
541	            }
542	        }
543	        Some("aa") | Some("protein") => {
544	            if args.len() < 2 { eprintln!("vox aa <one-letter amino-acid sequence>"); 1 }
545	            else { protein(&args[1..].join(""), "sequence") }
546	        }
547	        Some("fasta") => {
548	            if args.len() < 2 { eprintln!("vox fasta <file.fasta>"); 1 }
549	            else { match std::fs::read_to_string(&args[1]) {
550	                Ok(txt) => protein(&genetic::protein_from_fasta(&txt), &args[1]),
551	                Err(e) => { eprintln!("vox fasta: {}: {}", args[1], e); 1 }
552	            } }
553	        }
554	        Some("pdb") => {
555	            if args.len() < 2 { eprintln!("vox pdb <file.pdb>"); 1 }
556	            else { match std::fs::read_to_string(&args[1]) {
557	                Ok(txt) => protein(&genetic::protein_from_pdb(&txt), &args[1]),
558	                Err(e) => { eprintln!("vox pdb: {}: {}", args[1], e); 1 }
559	            } }
560	        }
561	        Some("glyco") => {
562	            if args.len() < 2 { eprintln!("vox glyco <seq | file.fasta | file.pdb>"); 1 }
563	            else {
564	                let a = &args[1];
565	                let loaded: Result<(String, String), String> = if a.ends_with(".pdb") {
566	                    std::fs::read_to_string(a).map(|t| (genetic::protein_from_pdb(&t), a.clone())).map_err(|e| e.to_string())
567	                } else if a.ends_with(".fasta") || a.ends_with(".fa") {
568	                    std::fs::read_to_string(a).map(|t| (genetic::protein_from_fasta(&t), a.clone())).map_err(|e| e.to_string())
569	                } else {
570	                    Ok((args[1..].join(""), "sequence".to_string()))
571	                };
572	                match loaded {
573	                    Ok((seq, src)) => glyco(&seq, &src),
574	                    Err(e) => { eprintln!("vox glyco: {a}: {e}"); 1 }
575	                }
576	            }
577	        }
578	        Some("self") => {
579	            let me = std::env::current_exe().map(|p| p.display().to_string())
580	                .unwrap_or_else(|_| "vox".into());
581	            selfread(&me)
582	        }
583	        Some("pyc") | Some("py") => {
584	            if args.len() < 2 { eprintln!("vox pyc <file.pyc>"); 1 } else { pyc_file(&args[1]) }
585	        }
586	        Some("findings") => {
587	            if args.len()<2 { eprintln!("vox findings <file>"); return; }
588	            let raw = read_or_exit(&args[1]);
589	            let l = loader::load(&raw);
590	            let image = vox_decode::Image { segments: l.code };
591	            let mut seeds: Vec<u64> = l.symbols.values().copied().collect(); seeds.push(l.entry);
592	            let w = vox_decode::walk(&image, l.entry, &seeds);
593	            let mut claimed: std::collections::BTreeSet<u64> = std::collections::BTreeSet::new();
594	            let mut b: Vec<(u64,String)> = Vec::new();
595	            for (start,f) in &w.functions {
596	                for ins in f { claimed.insert(ins.address); }
597	                let word = vox::recompile_function(f);
598	                if vox::verdict(&word)=='B' { b.push((*start, vox::glyphs(&word))); }
599	            }
600	            // sweep
601	            for (base,bytes) in &image.segments {
602	                let mut pos=0usize; let mut cur:Vec<x86::Insn>=Vec::new(); let mut fstart=*base;
603	                let mut flush=|cur:&mut Vec<x86::Insn>, fstart:u64, b:&mut Vec<(u64,String)>| {
604	                    if cur.is_empty(){return;} let word=alloc_word(cur);
605	                    if vox::verdict(&word)=='B' { b.push((fstart, vox::glyphs(&word))); } cur.clear();
606	                };
607	                while pos<bytes.len() {
608	                    let addr=base+pos as u64;
609	                    if claimed.contains(&addr){ flush(&mut cur,fstart,&mut b); if let Some(d)=x86::decode(&bytes[pos..],addr){pos+=d.len.max(1);}else{pos+=1;} continue; }
610	                    match x86::decode(&bytes[pos..],addr){
611	                        Some(d) if d.len>0 => { if cur.is_empty(){fstart=addr;} let mn=d.mnemonic.clone(); pos+=d.len; let term=mn.starts_with("ret")||matches!(mn.as_str(),"int3"|"ud2"|"hlt"|"jmp"); cur.push(d); if term{flush(&mut cur,fstart,&mut b);} }
612	                        _ => { flush(&mut cur,fstart,&mut b); pos+=1; }
613	                    }
614	                }
615	                flush(&mut cur,fstart,&mut b);
616	            }
617	            println!("{} B-finding(s): a fork held open across a commit or return.", b.len());
618	            println!("Inspect each; B is a candidate shape, not a proof.");
619	            for (a,word) in &b { println!("  0x{:x}  {}", a, word); }
620	            std::process::exit(0);
621	        }
622	        Some("run") => {
623	            // vox run <file> [--argv a,b]            — run it: real process, real
624	            //                                           argv/envp/auxv stack, real
625	            //                                           syscalls, from its own entry.
626	            // vox run <symbol> <file> [--args 1,2]   — call one function directly:
627	            //                                           scalar int args in, one
628	            //                                           int back, no process at all.
629	            // A single bare token is the FILE, not the symbol — with no name given
630	            // there is no function to call, so the whole file runs as a process.
631	            // This is also the only thing a PE binary offers, since the loader
632	            // never populates a symbol table for PE at all (only ELF has one).
633	            let mut bare: Vec<String> = Vec::new();
634	            let mut argv_ints: Vec<i64> = Vec::new();
635	            let mut argv_strs: Vec<String> = Vec::new();
636	            let mut i=1;
637	            while i < args.len() {
638	                match args[i].as_str() {
639	                    "--args" => { i+=1; if i<args.len() { for a in args[i].split(',') { let a=a.trim(); if !a.is_empty() {
640	                        let v = if let Some(h)=a.strip_prefix("0x") { i64::from_str_radix(h,16).unwrap_or(0) } else { a.parse().unwrap_or(0) }; argv_ints.push(v);} } } }
641	                    "--argv" => { i+=1; if i<args.len() { for a in args[i].split(',') { argv_strs.push(a.to_string()); } } }
642	                    other => bare.push(other.to_string()),
643	                }
644	                i+=1;
645	            }
646	            let (sym, file): (String, String) = match bare.len() {
647	                0 => { eprintln!("vox run <file> [--argv a,b]   or   vox run <symbol> <file> [--args 1,2]"); return; }
648	                1 => (String::new(), bare[0].clone()),
649	                _ => (bare[0].clone(), bare[1..].join(" ")),
650	            };
651	            if file.is_empty() { eprintln!("vox run <file> [--argv a,b]   or   vox run <symbol> <file> [--args 1,2]"); return; }
652	            // A `.imasm` file is a saved module: text, already carrying its own
653	            // symbol table (`; sym NAME 0xADDR`), so it runs directly with no
654	            // second read of the original binary. Anything else is read as raw
655	            // bytes and lifted fresh, same as before.
656	            let is_module = file.ends_with(".imasm")
657	                || std::fs::read(&file).map(|b| b.starts_with(b"; ")).unwrap_or(false);
658	            let mut m = if is_module {
659	                let text = match std::fs::read_to_string(&file) {
660	                    Ok(t) => t,
661	                    Err(e) => { eprintln!("cannot read {}: {}", file, e); std::process::exit(1); }
662	                };
663	                imasm_vm::Machine::new(&text)
664	            } else {
665	                let raw = read_or_exit(&file);
666	                imasm_vm::Machine::new(&imasm_module::emit(&raw))
667	            };
668	            m.set_host(Box::new(StdHost::new()));
669	            if sym.is_empty() {
670	                let mut argv = vec![file.clone()];
671	                argv.extend(argv_strs);
672	                match m.run_process(&argv, &[], 50_000_000) {
673	                    Ok(()) => println!("entry(...) ran off the end with no exit call   [{} steps]", m.steps),
674	                    Err(imasm_vm::Stop::SysExit(c)) => println!("entry(...) exited({})   [{} steps in the twelve]", c, m.steps),
675	                    Err(imasm_vm::Stop::Halt(e)) => println!("entry(...) halted: {}   [{} steps]", e, m.steps),
676	                }
677	            } else {
678	                let addr = match m.resolve(&sym) {
679	                    Some(a) => a,
680	                    None => { eprintln!("no symbol '{}' in {}", sym, file); std::process::exit(1); }
681	                };
682	                match m.call(addr, &argv_ints, 50_000_000) {
683	                    Ok(r) => println!("{}({}) = {}   [{} steps in the twelve]", sym, argv_ints.iter().map(|a|a.to_string()).collect::<Vec<_>>().join(", "), r, m.steps),
684	                    Err(imasm_vm::Stop::SysExit(c)) => println!("{}(...) called exit({})   [{} steps in the twelve]", sym, c, m.steps),
685	                    Err(imasm_vm::Stop::Halt(e)) => println!("{}(...) halted: {}   [{} steps]", sym, e, m.steps),
686	                }
687	            }
688	            std::process::exit(0);
689	        }
690	        Some("imasm") => { if args.len()<2 { eprintln!("vox imasm <file>"); return; }
691	            let raw=read_or_exit(&args[1]);
692	            let module = imasm_module::emit(&raw);
693	            print!("{}", module);
694	            let out_path = format!("{}.imasm", args[1]);
695	            match std::fs::write(&out_path, &module) {
696	                Ok(()) => eprintln!("saved {}", out_path),
697	                Err(e) => eprintln!("could not save {}: {}", out_path, e),
698	            }
699	            std::process::exit(0); }
700	        Some("word") | Some("words") => { if args.len()<2 { eprintln!("vox word <file>"); return; }
701	            let raw=read_or_exit(&args[1]); println!("{}", imasm_module::words(&raw)); std::process::exit(0); }
702	        Some("disasm") => {
703	            if args.len() < 2 { eprintln!("vox disasm <file> [symbol]"); return; }
704	            let raw = read_or_exit(&args[1]);
705	            let (entry, segments) = vox::parse_elf(&raw);
706	            let image = vox_decode::Image { segments };
707	            let seeds = vox::elf_function_symbols(&raw);
708	            let w = vox_decode::walk(&image, entry, &seeds);
709	            for (start, f) in &w.functions {
710	                if args.len() > 2 { /* filter by address later */ }
711	                let _ = start;
712	                for ins in f {
713	                    if let Some(bytes) = image.bytes_at(ins.address) {
714	                        if let Some(d) = x86::decode(bytes, ins.address) {
715	                            let ops: Vec<String> = d.ops.iter().map(|o| o.field()).collect();
716	                            println!("{:x}	{}	{}", d.addr, d.mnemonic, ops.join(" "));
717	                        } else {
718	                            println!("{:x}	??? (undecoded)", ins.address);
719	                        }
720	                    }
721	                }
722	            }
723	            std::process::exit(0);
724	        }
725	        Some("lift") => { if args.len() < 2 { eprintln!("vox lift <file>"); 1 } else { lift_file(&args[1]) } }
726	        Some(flag) if flag.starts_with('-') => { eprintln!("vox: unknown option {}\n", flag); usage(); 2 }
727	        Some(path) => lift_file(path),
728	    };
729	    std::process::exit(code);
730	}
