76	/// Chou-Fasman propensities as (helix, sheet, turn) × 100.
77	/// Source: gene_to_protein_pipeline.py CHOU_FASMAN dict.
78	fn chou_fasman(aa: AminoAcid) -> (u32, u32, u32) {
79	    match aa {
80	        AminoAcid::Ala  => (142, 83,  66),
81	        AminoAcid::Arg  => (98,  93,  95),
82	        AminoAcid::Asn  => (67,  89,  156),
83	        AminoAcid::Asp  => (101, 54,  146),
84	        AminoAcid::Cys  => (70,  119, 119),
85	        AminoAcid::Gln  => (111, 110, 98),
86	        AminoAcid::Glu  => (151, 37,  74),
87	        AminoAcid::Gly  => (57,  75,  156),
88	        AminoAcid::His  => (100, 87,  95),
89	        AminoAcid::Ile  => (108, 160, 47),
90	        AminoAcid::Leu  => (121, 130, 59),
91	        AminoAcid::Lys  => (116, 74,  101),
92	        AminoAcid::Met  => (145, 105, 60),
93	        AminoAcid::Phe  => (113, 138, 60),
94	        AminoAcid::Pro  => (57,  55,  152),
95	        AminoAcid::Ser  => (77,  75,  143),
96	        AminoAcid::Thr  => (83,  119, 96),
97	        AminoAcid::Trp  => (108, 137, 96),
98	        AminoAcid::Tyr  => (69,  147, 114),
99	        AminoAcid::Val  => (106, 170, 50),
100	        AminoAcid::Stop => (100, 100, 100),
101	    }
102	}
