116	/// Predict secondary and tertiary structure from an amino acid chain.
117	/// Returns a FoldResult with per-residue annotations and contact list.
118	pub fn fold_sequence(chain: &[AminoAcid]) -> FoldResult {
119	    let n = chain.len();
120	    if n == 0 {
121	        return FoldResult {
122	            residues: alloc::vec::Vec::new(),
123	            contacts: alloc::vec::Vec::new(),
124	            frobenius_ok: true,
125	            unique_primitives: 0,
126	            ouroboricity_tier: "O_0",
127	        };
128	    }
129	
130	    // ── Secondary structure (Chou-Fasman-like) ──────────────────
131	    let mut pred = alloc::vec![SecondaryLabel::Coil; n];
132	
133	    // Alpha-helix: window=4, sum > 4*103 = 412; extend while individual > 100
134	    {
135	        let mut i = 0;
136	        while i + 4 <= n {
137	            let sum: u32 = chain[i..i+4].iter().map(|&a| chou_fasman(a).0).sum();
138	            if sum > 412 {
139	                let mut j = i + 4;
140	                while j < n && chou_fasman(chain[j]).0 > 100 {
141	                    j += 1;
142	                }
143	                for k in i..j { pred[k] = SecondaryLabel::Helix; }
144	                i = j;
145	            } else {
146	                i += 1;
147	            }
148	        }
149	    }
150	
151	    // Beta-sheet: window=3, sum > 3*105 = 315; skip positions already helix; extend while > 100
152	    {
153	        let mut i = 0;
154	        while i + 3 <= n {
155	            let already_h = (i..i+3).any(|k| pred[k] == SecondaryLabel::Helix);
156	            if !already_h {
157	                let sum: u32 = chain[i..i+3].iter().map(|&a| chou_fasman(a).1).sum();
158	                if sum > 315 {
159	                    let mut j = i + 3;
160	                    while j < n && chou_fasman(chain[j]).1 > 100 && pred[j] != SecondaryLabel::Helix {
161	                        j += 1;
162	                    }
163	                    for k in i..j { pred[k] = SecondaryLabel::Sheet; }
164	                    i = j;
165	                } else {
166	                    i += 1;
167	                }
168	            } else {
169	                i += 1;
170	            }
171	        }
172	    }
173	
174	    // ── Tertiary contacts ────────────────────────────────────────
175	    let mut contacts: alloc::vec::Vec<TertiaryContact> = alloc::vec::Vec::new();
176	    let min_seq_dist = { let d = n / 4; if d < 2 { 2 } else if d > 4 { 4 } else { d } };
177	
178	    // Hydrophobic contacts: pairs of hydrophobic residues > min_seq_dist apart
179	    {
180	        let hydro: alloc::vec::Vec<usize> = (0..n).filter(|&k| is_hydrophobic(chain[k])).collect();
181	        for a in 0..hydro.len() {
182	            for b in a+1..hydro.len() {
183	                let (pi, pj) = (hydro[a], hydro[b]);
184	                if pj - pi > min_seq_dist {
185	                    let conf = {
186	                        let diff = (pj - pi) as u32;
187	                        let nv = n as u32;
188	                        if diff >= nv { 20u8 } else { (90u32.saturating_sub(diff * 70 / nv.max(1))) as u8 }
189	                    };
190	                    contacts.push(TertiaryContact { i: pi, j: pj, kind: ContactKind::Hydrophobic, confidence: conf });
191	                }
192	            }
193	        }
194	    }
195	
196	    // Disulfide bonds: Cys-Cys pairs with 4 <= |i-j| <= 200
197	    {
198	        let cys: alloc::vec::Vec<usize> = (0..n).filter(|&k| chain[k] == AminoAcid::Cys).collect();
199	        for a in 0..cys.len() {
200	            for b in a+1..cys.len() {
201	                let d = cys[b] - cys[a];
202	                if d >= 4 && d <= 200 {
203	                    contacts.push(TertiaryContact { i: cys[a], j: cys[b], kind: ContactKind::Disulfide, confidence: 80 });
204	                }
205	            }
206	        }
207	    }
208	
209	    // Ionic contacts: positive × negative residues, 3 < |i-j| < 0.8n
210	    {
211	        let pos_c: alloc::vec::Vec<usize> = (0..n).filter(|&k| signed_charge(chain[k]) > 0).collect();
212	        let neg_c: alloc::vec::Vec<usize> = (0..n).filter(|&k| signed_charge(chain[k]) < 0).collect();
213	        let lim = (n * 4) / 5;
214	        for &pi in &pos_c {
215	            for &pj in &neg_c {
216	                let sd = if pj > pi { pj - pi } else { pi - pj };
217	                if sd > 3 && sd < lim {
218	                    let conf = (70u32.saturating_sub(sd as u32 * 70 / (n as u32).max(1))) as u8;
219	                    contacts.push(TertiaryContact {
220	                        i: pi.min(pj), j: pi.max(pj),
221	                        kind: ContactKind::Ionic, confidence: conf,
222	                    });
223	                }
224	            }
225	        }
226	    }
227	
228	    // Deduplicate by (i,j), keeping highest confidence
229	    contacts.sort_unstable_by(|a, b| a.i.cmp(&b.i).then(a.j.cmp(&b.j)).then(b.confidence.cmp(&a.confidence)));
230	    contacts.dedup_by(|a, b| a.i == b.i && a.j == b.j);
231	
232	    // ── Per-residue contact count ────────────────────────────────
233	    let mut contact_count = alloc::vec![0usize; n];
234	    for c in &contacts {
235	        if c.i < n { contact_count[c.i] += 1; }
236	        if c.j < n { contact_count[c.j] += 1; }
237	    }
