14	/// Transcription: DNA coding strand → mRNA (T→U only, NO complement).
15	/// DNA: ATGGCC → mRNA: AUGGCC. The coding strand IS the mRNA with T→U.
16	pub fn transcribe(dna: &[u8]) -> Vec<u8> {
17	    dna.iter().map(|&b| {
18	        match b {
19	            b'T' | b't' => b'U',
20	            other => other.to_ascii_uppercase(),
21	        }
22	    }).collect()
23	}
24	
25	/// Reverse transcription: mRNA → DNA (U→T, no complement).
26	/// mRNA: AUGGCC → DNA: ATGGCC. Just U→T.
27	pub fn reverse_transcribe(mrna: &[u8]) -> Vec<u8> {
28	    mrna.iter().map(|&b| {
29	        match b {
30	            b'U' | b'u' => b'T',
31	            other => other.to_ascii_uppercase(),
32	        }
33	    }).collect()
34	}
