36	/// Translation: mRNA → amino acid chain.
37	/// Finds the first AUG (start), translates codons, stops at stop codon.
38	pub fn translate(mrna: &[u8]) -> (Vec<AminoAcid>, usize) {
39	    let mut chain = Vec::new();
40	    let mut start_idx = None;
41	
42	    // Find start codon (AUG)
43	    for i in 0..mrna.len().saturating_sub(2) {
44	        if mrna[i] == b'A' && mrna[i+1] == b'U' && mrna[i+2] == b'G' {
45	            start_idx = Some(i);
46	            break;
47	        }
48	    }
49	
50	    let start = match start_idx {
51	        Some(i) => i,
52	        None => return (chain, 0),
53	    };
54	
55	    // Translate codons from start
56	    let mut pos = start;
57	    while pos + 2 < mrna.len() {
58	        let codon = match Codon::from_bytes(mrna[pos], mrna[pos+1], mrna[pos+2]) {
59	            Ok(c) => c,
60	            Err(_) => break,
61	        };
62	        let aa = translate_codon(&codon);
63	        if aa == AminoAcid::Stop {
64	            chain.push(aa); // record stop
65	            break;
66	        }
67	        chain.push(aa);
68	        pos += 3;
69	    }
70	
71	    (chain, pos + 3 - start)
72	}
