78	pub fn parse_aa(s: &str) -> Option<AminoAcid> {
79	    match s.to_uppercase().as_str() {
80	        // Three-letter codes
81	        "PHE" | "F" => Some(AminoAcid::Phe),
82	        "LEU" | "L" => Some(AminoAcid::Leu),
83	        "ILE" | "I" => Some(AminoAcid::Ile),
84	        "MET" | "M" => Some(AminoAcid::Met),
85	        "VAL" | "V" => Some(AminoAcid::Val),
86	        "SER" | "S" => Some(AminoAcid::Ser),
87	        "PRO" | "P" => Some(AminoAcid::Pro),
88	        "THR" | "T" => Some(AminoAcid::Thr),
89	        "ALA" | "A" => Some(AminoAcid::Ala),
90	        "TYR" | "Y" => Some(AminoAcid::Tyr),
91	        "STOP" | "STP" | "*" => Some(AminoAcid::Stop),
92	        "HIS" | "H" => Some(AminoAcid::His),
93	        "GLN" | "Q" => Some(AminoAcid::Gln),
94	        "ASN" | "N" => Some(AminoAcid::Asn),
95	        "LYS" | "K" => Some(AminoAcid::Lys),
96	        "ASP" | "D" => Some(AminoAcid::Asp),
97	        "GLU" | "E" => Some(AminoAcid::Glu),
98	        "CYS" | "C" => Some(AminoAcid::Cys),
99	        "TRP" | "W" => Some(AminoAcid::Trp),
100	        "ARG" | "R" => Some(AminoAcid::Arg),
