121	/// The result of reverse-translating a single amino acid:
122	/// one or more codons that could encode it.
123	#[derive(Debug)]
124	pub struct ReverseHit {
125	    pub aa: AminoAcid,
126	    pub codons: Vec<Codon>,
127	    pub codon_count: usize,     // degeneracy
128	}
129	
130	/// Reverse translate an amino acid: return ALL codons that encode it.
131	pub fn reverse_translate_aa(aa: AminoAcid) -> ReverseHit {
132	    use crate::rebis::genetics::codons_for_aa;
133	    let codons = codons_for_aa(aa);
134	    ReverseHit {
135	        aa,
136	        codon_count: codons.len(),
137	        codons,
138	    }
139	}
