141	/// Format a codon as a 3-letter RNA string.
142	pub fn codon_to_rna(c: &Codon) -> [u8; 3] {
143	    [b4_to_nucleotide(c.p1), b4_to_nucleotide(c.p2), b4_to_nucleotide(c.p3)]
144	}
145	
146	/// Reverse translate a full protein chain to ALL possible mRNA sequences.
147	/// Returns a vector where each element is the set of possible codons for that position.
148	pub fn reverse_translate_chain(chain: &[AminoAcid]) -> Vec<ReverseHit> {
149	    chain.iter().map(|&aa| reverse_translate_aa(aa)).collect()
150	}
151	
152	/// Enumerate ALL possible mRNA sequences for a protein chain.
153	/// WARNING: Product of degeneracies. A chain of 4 AAs averaging 4 codons
154	/// each produces 4^4=256 sequences. Use with care.
155	/// Returns the total count and an iterator-like Vec of sequences.
156	pub fn enumerate_mrna(chain: &[AminoAcid]) -> Vec<Vec<u8>> {
157	    if chain.is_empty() {
158	        return Vec::new();
159	    }
160	
161	    use crate::rebis::genetics::codons_for_aa;
162	
163	    // Start with the first AA's codons
164	    let first = codons_for_aa(chain[0]);
165	    if first.is_empty() {
166	        return Vec::new();
167	    }
168	
169	    let mut sequences: Vec<Vec<u8>> = first.iter().map(|c| {
170	        Vec::from(codon_to_rna(c).as_slice())
171	    }).collect();
172	
173	    // For each subsequent AA, extend all sequences with its codons
174	    for &aa in &chain[1..] {
175	        let codons = codons_for_aa(aa);
176	        if codons.is_empty() {
177	            break;
178	        }
179	        let mut new_seqs = Vec::with_capacity(sequences.len() * codons.len());
180	        for seq in &sequences {
181	            for c in &codons {
182	                let mut ext = seq.clone();
183	                ext.extend_from_slice(&codon_to_rna(c));
184	                new_seqs.push(ext);
185	            }
186	        }
187	        sequences = new_seqs;
188	    }
189	
190	    sequences
191	}
