193	/// Reverse translation: amino acid chain → canonical codon sequence.
194	/// For each AA, returns the FIRST codon (sorted by index, which groups U→A→C→G).
195	/// This is the "canonical" representative.
196	pub fn reverse_translate(chain: &[AminoAcid]) -> Vec<u8> {
197	    use crate::rebis::genetics::codons_for_aa;
198	    let mut mrna = Vec::new();
199	    for &aa in chain {
200	        let codons = codons_for_aa(aa);
201	        if codons.is_empty() { break; }
202	        let c = &codons[0];
203	        mrna.push(b4_to_nucleotide(c.p1));
204	        mrna.push(b4_to_nucleotide(c.p2));
205	        mrna.push(b4_to_nucleotide(c.p3));
206	    }
207	    mrna
208	}
