27	
28	const AA_TO_CODON: [(&str, &str); 21] = [
29	    ("A", "GCU"), ("R", "CGU"), ("N", "AAU"), ("D", "GAU"), ("C", "UGU"),
30	    ("Q", "CAA"), ("E", "GAA"), ("G", "GGU"), ("H", "CAU"), ("I", "AUU"),
