116	/// Extract long-range contacts: Cα distance < cutoff, sequence sep ≥ min_seq_dist.
117	pub fn extract_contacts(atoms: &[CAAtom], cutoff: f64, min_seq_dist: usize) -> alloc::vec::Vec<Contact> {
118	    let mut contacts = Vec::new();
119	    let mut seen: alloc::vec::Vec<(usize, usize)> = alloc::vec::Vec::new();
120	
121	    for i in 0..atoms.len() {
122	        for j in (i + 1)..atoms.len() {
123	            let seq_dist = (atoms[i].res_num - atoms[j].res_num).unsigned_abs() as usize;
124	            if seq_dist < min_seq_dist { continue; }
125	
126	            let dist = ca_distance(&atoms[i], &atoms[j]);
