180	/// Compute precision, recall, F1 for predicted vs actual contacts.
181	pub fn compute_metrics(
182	    predicted: &[(usize, usize)],
183	    actual: &[(usize, usize)],
184	) -> ValidationMetrics {
185	    let pred_set: BTreeSet<(usize, usize)> = predicted.iter()
186	        .map(|&(i, j)| if i < j { (i, j) } else { (j, i) })
187	        .collect();
188	    let actual_set: BTreeSet<(usize, usize)> = actual.iter()
189	        .map(|&(i, j)| if i < j { (i, j) } else { (j, i) })
190	        .collect();
191	
192	    let tp = pred_set.intersection(&actual_set).count();
193	    let fp = pred_set.len() - tp;
194	    let fn_count = actual_set.len() - tp;
195	
196	    let precision = if tp + fp > 0 { tp as f64 / (tp + fp) as f64 } else { 0.0 };
197	    let recall = if tp + fn_count > 0 { tp as f64 / (tp + fn_count) as f64 } else { 0.0 };
198	    let f1 = if precision + recall > 0.0 {
199	        2.0 * precision * recall / (precision + recall)
200	    } else {
201	        0.0
202	    };
203	
204	    ValidationMetrics {
205	        true_positives: tp,
206	        false_positives: fp,
207	        false_negatives: fn_count,
