1	// rebis/genetics.rs — B₄ Nucleotide Lattice & Genetic Code Operations
2	//
3	// Port of rhr_p4rky/genetics_b4.py and genetic_code.py.
4	// B₄ lattice operations on codons, Frobenius stratum classification,
5	// and the 12-primitive ↔ 20 amino acid structural mapping.
6	
7	use crate::belnap::{B4, meet, join};
8	use crate::rebis::codon::{Codon, CodeTable, Stratum, classify_stratum, translate_codon, translate_codon_mito, wc_complement};
9	use crate::rebis::AminoAcid;
10	
11	// ── B₄ lattice operations on nucleotides ───────────────────────
12	
13	/// B₄ meet (∧): greatest lower bound.
14	/// G∧G=G, C∧C=C, A∧A=A, U∧U=U; G∧x=x for all x.
15	pub fn b4_meet(a: B4, b: B4) -> B4 {
16	    meet(a, b)
17	}
18	
19	/// B₄ join (∨): least upper bound.
20	/// G∨x=G for all x; A∨x=x for all x; C∨U=G.
21	pub fn b4_join(a: B4, b: B4) -> B4 {
22	    join(a, b)
23	}
24	
25	/// B₄ complement: Watson-Crick (fixed-point-free involution).
26	pub fn b4_complement(a: B4) -> B4 {
27	    wc_complement(a)
28	}
29	
30	// ── Codon lattice operations ────────────────────────────────────
31	
32	/// Pointwise B₄ meet of two codons.
33	pub fn codon_meet(a: &Codon, b: &Codon) -> Codon {
34	    Codon {
